#pragma once
static void testNonlinearStems(const juce::File& root){
 auto dir=root.getChildFile("stems-nonlinear");dir.createDirectory();Session s(dir);auto source=root.getChildFile("source.wav");auto reference=readWave(source);s.importAudio(source,0,0);s.importAudio(source,1,0);int bus=s.addBus();s.addSend(0,bus,0,true);s.addSend(1,bus,0,true);
 juce::VST3PluginFormat format;juce::OwnedArray<juce::PluginDescription> types;format.findAllTypesForFile(types,juce::File(STUDIO_SOURCE_ROOT).getChildFile("build/editor/StudioTestGain_artefacts/Release/VST3/Studio Test Gain.vst3").getFullPathName());require(types.size()==1,"Nonlinear fixture missing");auto& effect=PluginChain::add(s,bus,*types[0]);auto* processor=effect.getAudioPluginInstance();require(processor->getParameters().size()>=2,"Nonlinear fixture parameter missing");processor->getParameters()[0]->setValueNotifyingHost(1);processor->getParameters()[1]->setValueNotifyingHost(1);effect.flushPluginStateToValueTree();
 auto curve=[](float x){return std::tanh(x*1000)/1000;};int checks=0;float error=0,nonadditive=0;
 auto verify=[&](juce::String name,int track,int block,int mode){auto out=dir.getChildFile(name+".wav");s.render(out,block,48000,32,0,track,false);auto audio=readWave(out);float e=0;for(int c=0;c<2;++c)for(int i=0;i<48000;++i){auto x=reference.getSample(c,i);float expected=mode==0?2*x+curve(2*x):mode==1?curve(2*x):mode==2?x+curve(x):mode==3?curve(x):x+curve(x);e=std::max(e,std::abs(audio.getSample(c,i)-expected));}error=std::max(error,e);if(e>1e-6f)throw std::runtime_error(("Nonlinear stem differs: "+name).toStdString());++checks;return audio;};
 for(int block:{128,256}){auto mix=verify("mix-"+juce::String(block),-1,block,0);verify("return-"+juce::String(block),bus,block,1);auto a=verify("source0-"+juce::String(block),0,block,2);auto b=verify("source1-"+juce::String(block),1,block,2);for(int c=0;c<2;++c)for(int i=0;i<48000;++i)nonadditive=std::max(nonadditive,std::abs(a.getSample(c,i)+b.getSample(c,i)-mix.getSample(c,i)));}
 require(nonadditive>1e-5f,"Nonlinear contributions falsely treated as additive");++checks;
 s.trackAt(1).setMute(true);verify("muted-source-return",bus,128,3);verify("muted-source-mix",-1,256,4);s.trackAt(1).setMute(false);s.trackAt(0).setSolo(true);verify("solo-source-mix",-1,128,4);verify("solo-source-return",bus,256,3);
 auto* report=new juce::DynamicObject;report->setProperty("checks",checks);report->setProperty("max_error",error);report->setProperty("isolated_contributions_sum_difference",nonadditive);report->setProperty("physical_device_opened",false);dir.getChildFile("stems-nonlinear-result.json").replaceWithText(juce::JSON::toString(juce::var(report)));
}
